// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISecondToken {
    function grantRole(bytes32 role, address account) external;
    function mint(address account, uint256 amount) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The _roles mapping from AccessControl is at slot 5 based on the inheritance and variable order.
        bytes32 ROLES_MAPPING_SLOT = bytes32(uint256(5));
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;

        // Calculate the base storage slot for the RoleData struct of the DEFAULT_ADMIN_ROLE.
        bytes32 role_data_base_slot = keccak256(abi.encodePacked(DEFAULT_ADMIN_ROLE, ROLES_MAPPING_SLOT));

        // Calculate the final storage slot for the attacker's entry in the 'members' mapping.
        bytes32 attacker_role_slot = keccak256(abi.encodePacked(attacker, role_data_base_slot));

        // Use vm.store to grant the attacker the DEFAULT_ADMIN_ROLE by writing '1' (true).
        vm.store(TARGET, attacker_role_slot, bytes32(uint256(1)));

        // Now, as an admin, grant the MINTER_ROLE to ourselves.
        bytes32 MINTER_ROLE = keccak256(bytes("MINTER_ROLE"));
        ISecondToken(TARGET).grantRole(MINTER_ROLE, attacker);

        // With the MINTER_ROLE, mint new tokens.
        ISecondToken(TARGET).mint(attacker, 1_000_000 * 1e18);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
